}
.cid-comment-sheet-actions .cid-fb-comment-reply,
.cid-comment-replies-toggle {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: #65676b;
  font: inherit;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
}
.cid-comment-reaction-group {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.cid-comment-like-badge {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-height: 20px;
  padding: 0 4px;
  border-radius: 999px;
  color: #65676b;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}
.cid-comment-like-badge span {
  font-size: 12px;
}
.cid-comment-reaction {
  display: grid;
  width: 26px;
  height: 24px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: #8a8d91;
  cursor: pointer;
}
.cid-comment-reaction svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}
.cid-comment-reaction:hover,
.cid-comment-reaction:focus-visible,
.cid-comment-reaction.is-active {
  background: #e7f3ff;
  color: #1877f2;
  outline: 0;
}
.cid-comment-reaction.is-dislike.is-active {
  background: #fff1f2;
  color: #d6293e;
}
.cid-comment-replies-toggle:hover,
.cid-comment-replies-toggle:focus-visible,
.cid-comment-sheet-actions .cid-fb-comment-reply:hover,
.cid-comment-sheet-actions .cid-fb-comment-reply:focus-visible {
  color: #1877f2;
  outline: 0;
}
.cid-comment-sheet-replies {
  margin-top: 2px;
}
.cid-fb-comment-status {
  display: inline-block;
  margin-left: 5px;
  color: #b06b00;
  font-size: 10px;
  font-weight: 800;
  text-transform: capitalize;
}
.cid-comments-sheet-loading,
.cid-comments-sheet-empty {
  display: grid;
  min-height: 180px;
  place-content: center;
  justify-items: center;
  gap: 8px;
