}
.cid-comments-sheet-empty-icon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 50%;
  background: #e7f3ff;
  font-size: 22px;
}
.cid-comments-sheet-status {
  min-height: 0;
  padding: 0 16px 7px;
  color: #1769c2;
  font-size: 11px;
  font-weight: 800;
}
.cid-comments-closed {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
