  color: #8a5a12;
  font-size: 13px;
}
.cid-comments-closed[hidden] { display: none; }
.cid-comments-closed-icon { font-size: 16px; }
.cid-comments-closed strong { font-weight: 700; }
.cid-comments-composer {
  flex: 0 0 auto;
  padding: 7px 12px calc(10px + env(safe-area-inset-bottom));
  border-top: 1px solid #edf0f4;
  background: rgba(255, 255, 255, .98);
}
.cid-comments-sheet-root.is-guest .cid-comments-composer {
  display: none !important;
}
.cid-comments-reply-context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 3px 6px 45px;
  color: #65676b;
  font-size: 11px;
}
.cid-comments-reply-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.cid-comments-reply-context strong {
  color: #1877f2;
}
.cid-comments-reply-quote {
  display: block;
  max-width: 100%;
  overflow: hidden;
  color: #8a8d91;
  font-size: 10px;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cid-comments-reply-clear {
  flex: 0 0 auto;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: #65676b;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
}
.cid-comments-reply-clear:hover,
.cid-comments-reply-clear:focus-visible {
  color: #1877f2;
  outline: 0;
}
.cid-comments-composer-row {
  display: flex;
  align-items: flex-end;
  min-width: 0;
  gap: 8px;
}
.cid-comments-composer-input {
  display: block;
  width: auto;
  min-width: 0;
  flex: 1 1 auto;
  min-height: 40px;
  max-height: 110px;
  overflow-y: auto;
  padding: 10px 13px;
  border: 1px solid #d7dce3;
  border-radius: 21px;
  outline: 0;
  background: #f0f2f5;
  color: #1c1e21;
  font: inherit;
  font-size: 13px;
  line-height: 1.35;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  cursor: text;
  resize: none;
  -webkit-appearance: none;
}
.cid-comments-composer-input::placeholder {
  color: #8a8d91;
  opacity: 1;
}
.cid-comment-mention {
  color: #1877f2;
  font-weight: 700;
  white-space: nowrap;
}
.cid-comments-composer-input:focus {
  border-color: #96bff1;
  background: #fff;
  box-shadow: 0 0 0 2px #e7f3ff;
}
.cid-comments-composer-submit {
  display: grid;
  width: auto;
  min-width: 78px;
  height: 40px;
  flex: 0 0 auto;
  place-items: center;
  padding: 0 14px;
  border: 0;
  border-radius: 20px;
  background: #1877f2;
  color: #fff;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  transition: transform 150ms ease, opacity 150ms ease;
}
.cid-comments-composer-submit[hidden],
.cid-comments-composer-emoji[hidden] {
  display: none !important;
}
.cid-comments-composer-submit:disabled {
  opacity: .45;
  cursor: default;
}
.cid-comments-composer-submit:not(:disabled):active {
  transform: scale(.92);
}
.cid-comments-composer-emoji {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: #f0f2f5;
  color: #1877f2;
  font-size: 24px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  transition: transform 150ms ease, background 150ms ease;
}
.cid-comments-composer-emoji:hover,
.cid-comments-composer-emoji:focus-visible {
  background: #e7f3ff;
  outline: none;
}
.cid-comments-composer-emoji:active {
  transform: scale(.92);
}
.cid-comments-emoji-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 7px 0 0 45px;
  padding: 7px;
  border: 1px solid #e1e6ee;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 6px 18px rgba(15, 23, 42, .10);
}
.cid-comments-emoji-picker[hidden] {
  display: none !important;
}
.cid-comments-emoji-picker button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 9px;
  background: transparent;
  font-size: 20px;
  cursor: pointer;
}
.cid-comments-emoji-picker button:hover,
.cid-comments-emoji-picker button:focus-visible {
  background: #f0f2f5;
  outline: none;
}
