  border-radius: 11px;
  background: #f8fafc;
  color: #61708d;
  font-size: .84rem;
  line-height: 1.5;
}
.cid-public-virtual__access {
  margin: 0 0 14px;
  padding: 9px 12px;
  border: 1px solid rgba(9, 98, 214, .14);
  border-radius: 10px;
  background: #f5f9ff;
  color: #0962d6;
  font-size: .82rem;
  font-weight: 800;
}
.cid-public-virtual__auth-gate {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-top: 8px;
  padding: 16px;
  border: 1px solid #d8e7fb;
  border-radius: 14px;
  background: #f7fbff;
  color: #0a1840;
}
.cid-public-virtual__auth-gate h3,
.cid-public-virtual__auth-gate p { margin: 0; }
.cid-public-virtual__auth-gate h3 { font-size: 1rem; }
.cid-public-virtual__auth-gate p {
  margin-top: 5px;
  color: #61708d;
  font-size: .85rem;
  line-height: 1.5;
}
.cid-public-virtual__auth-gate .resultat-aide-button { margin-top: 12px; }
.cid-public-virtual__auth-icon {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 10px;
  background: #e6f0ff;
  color: #0962d6;
  font-weight: 900;
}
.cid-public-virtual .support-chat-message { align-self: flex-start; }
.cid-public-virtual .support-chat-message.is-user { align-self: flex-end; }
.cid-pending-confirmation {
  margin: 0 0 10px;
  padding: 12px 13px;
  border: 1px solid #f0c36d;
  border-radius: 12px;
  background: #fffaf0;
  color: #5f430b;
}
.cid-pending-confirmation strong,
.cid-pending-confirmation p {
  display: block;
  margin: 0;
}
.cid-pending-confirmation p {
  margin-top: 5px;
  font-size: .82rem;
  line-height: 1.45;
}
.cid-pending-confirmation__question { font-weight: 800; }
.cid-pending-confirmation__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
@media (max-width: 680px) {
  .resultat-aide-panel { margin-inline: 10px; width: auto; padding: 14px; }
  .resultat-aide-header { flex-direction: column; }
  .cid-public-virtual__auth-gate { padding: 13px; }
}
.resultat-aide-draw-card {
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.resultat-aide-draw-card-trigger {
  --result-card-accent: #1877f2;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
  box-sizing: border-box;
  padding: 22px 24px 24px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-left: 4px solid var(--result-card-accent);
  border-radius: 12px;
  background: #222c3d;
  color: #edf1f7;
  cursor: pointer;
  font: inherit;
  text-align: left;
  box-shadow: 0 9px 24px rgba(27, 46, 75, .16);
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.resultat-aide-country-heading {
  display: none;
}
.resultat-aide-country-cards {
  gap: 18px;
}
.resultat-aide-draw-card-trigger:hover,
.resultat-aide-draw-card-trigger:focus-visible {
  border-color: rgba(255, 255, 255, .24);
  outline: 0;
  box-shadow: 0 13px 28px rgba(27, 46, 75, .23);
  transform: translateY(-2px);
}
.resultat-aide-draw-card-trigger:focus-visible {
  box-shadow: 0 0 0 4px rgba(126, 174, 235, .3), 0 13px 28px rgba(27, 46, 75, .23);
}
.resultat-aide-draw-card-header {
  display: flex;
  flex-direction: column;
  align-items: start;
  gap: 8px;
  width: 100%;
  padding: 0 0 18px;
  border: 0;
  background: transparent;
}
.resultat-aide-draw-card-header strong {
  min-width: 0;
  color: #f4f6fa;
  font-size: clamp(1.15rem, 3.5vw, 1.55rem);
  line-height: 1.25;
  font-weight: 900;
  overflow-wrap: anywhere;
}
@supports (color: color-mix(in srgb, #000 50%, #fff)) {
  .resultat-aide-draw-card-trigger {
    border-color: color-mix(in srgb, var(--result-card-accent) 38%, rgba(255, 255, 255, .14));
    background:
      linear-gradient(135deg,
        color-mix(in srgb, #222c3d 91%, var(--result-card-accent)),
        #222c3d 68%);
  }

  .resultat-aide-draw-card-header strong {
    color: color-mix(in srgb, var(--result-card-accent) 64%, #f4f6fa);
  }

  .resultat-aide-draw-card-body {
    border-top-color: color-mix(in srgb, var(--result-card-accent) 42%, rgba(255, 255, 255, .16));
  }
}
.resultat-aide-draw-card-header span {
  color: #d1d8e3;
  font-size: clamp(.9rem, 2.2vw, 1rem);
  line-height: 1.35;
  font-weight: 700;
}
.resultat-aide-draw-card-date,
.resultat-aide-draw-card-number {
  display: block;
}
.resultat-aide-draw-card-number {
  margin-top: 0;
  color: #edf1f7 !important;
  font-weight: 800 !important;
}
.resultat-aide-draw-card-body {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
  padding: 16px 0 0;
  border-top: 1px solid rgba(255, 255, 255, .16);
}
.resultat-aide-draw-preview-line {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  width: 100%;
  min-width: 0;
  color: #f0f3f8;
  font-size: clamp(1rem, 2.9vw, 1.2rem);
  line-height: 1.5;
}
.resultat-aide-draw-preview-line > span {
  flex: 0 0 auto;
  font-weight: 850;
}
.resultat-aide-draw-preview-line strong {
  min-width: 0;
  color: #f0f3f8;
  font-weight: 900;
  letter-spacing: .01em;
  overflow-wrap: anywhere;
}
.resultat-aide-draw-preview-line.is-bonus,
.resultat-aide-draw-preview-line.is-bonus strong {
  color: #ffc56b;
}
.resultat-aide-result-modal[hidden] {
  display: none !important;
}
.resultat-aide-result-modal {
  position: fixed;
  z-index: 2000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 18px;
}
.resultat-aide-result-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(12, 24, 42, .48);
  backdrop-filter: blur(5px);
}
.resultat-aide-result-dialog {
  position: relative;
  width: min(620px, 100%);
  max-height: min(720px, calc(100vh - 36px));
  overflow: auto;
  border: 1px solid rgba(255, 255, 255, .72);
  border-radius: 22px;
  background: #fff;
  color: #111827;
  box-shadow: 0 24px 75px rgba(7, 18, 32, .28);
  animation: resultat-aide-modal-in .18s ease-out both;
}
@keyframes resultat-aide-modal-in {
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.resultat-aide-result-dialog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 24px 24px 18px;
  border-bottom: 1px solid #edf0f4;
}
.resultat-aide-result-dialog-kicker {
  display: block;
  margin-bottom: 5px;
  color: #37a653;
  font-size: .7rem;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.resultat-aide-result-dialog h2,
.resultat-aide-result-dialog p {
  margin: 0;
}
.resultat-aide-result-dialog h2 {
  color: #101010;
  font-size: clamp(1.35rem, 4vw, 1.8rem);
}
.resultat-aide-result-dialog p {
  display: grid;
  gap: 2px;
  margin-top: 7px;
  color: #7c8797;
  font-size: .82rem;
  font-weight: 700;
  line-height: 1.55;
}
.resultat-aide-result-dialog-draw-number {
  color: #253044;
}
.resultat-aide-result-modal-close {
  display: grid;
  flex: 0 0 auto;
  width: 35px;
  height: 35px;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: #f1f4f7;
  color: #334155;
  cursor: pointer;
  font: 500 1.5rem/1 Arial, sans-serif;
}
.resultat-aide-result-modal-close:hover,
.resultat-aide-result-modal-close:focus-visible {
  background: #e4f3e8;
  color: #24843d;
  outline: 0;
}
.resultat-aide-result-dialog-body {
  display: grid;
  gap: 7px;
  padding: 21px 24px 25px;
}
.resultat-aide-result-line {
  display: block;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: #37a653;
  font-size: clamp(1.22rem, 4.2vw, 1.8rem);
  line-height: 1.38;
}
.resultat-aide-result-line-label {
  color: #37a653;
  font-size: inherit;
  font-weight: 900;
  letter-spacing: .01em;
}
.resultat-aide-result-line strong {
  color: #37a653;
  font-size: inherit;
  letter-spacing: .015em;
}
.resultat-aide-result-line.is-bonus {
  color: #c56b13;
}
.resultat-aide-result-line.is-bonus .resultat-aide-result-line-label,
.resultat-aide-result-line.is-bonus strong {
  color: #c56b13;
}
body.resultat-aide-modal-open {
  overflow: hidden;
}
@media (max-width: 560px) {
  .resultat-aide-draw-card-trigger {
    padding: 18px 16px 20px;
    border-radius: 12px;
  }

  .resultat-aide-draw-card-header {
    align-items: start;
    justify-content: start;
    flex-direction: column;
    gap: 8px;
  }

  .resultat-aide-draw-preview-line {
    gap: 5px;
    font-size: 1rem;
  }

  .resultat-aide-result-modal {
    align-items: end;
    padding: 0;
  }

  .resultat-aide-result-dialog {
    max-height: calc(100vh - 10px);
    border-radius: 21px 21px 0 0;
  }

  .resultat-aide-result-dialog-header {
    padding: 20px 17px 16px;
  }

  .resultat-aide-result-dialog-body {
    padding: 17px 17px 22px;
  }
}

/*  ==== src/shared/balance-panel.css ====  */
.cid-balance-dialog {
  position: relative;
  z-index: 2;
  width: min(100%, 720px);
  box-sizing: border-box;
  margin: 0 auto;
  padding: 0 0 140px;
}
.cid-balance-dialog[hidden] {
  display: none !important;
}
.cid-balance-card {
  width: 100%;
  overflow: visible;
  border: 1px solid rgba(255, 255, 255, .78);
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 12px 34px rgba(5, 19, 48, .12);
}
.cid-balance-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 22px 22px 19px;
  color: #fff;
  background:
    radial-gradient(circle at 88% 6%, rgba(255, 255, 255, .24), transparent 34%),
    linear-gradient(135deg, #0962d6, #0a3d98);
}
.cid-balance-card__eyebrow {
  display: block;
  margin: 0 0 4px;
  color: rgba(255, 255, 255, .76);
  font: 800 10px/1.2 'Noto Sans', sans-serif;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.cid-balance-card h2 {
  margin: 0;
  font: 900 24px/1.1 'Noto Sans', sans-serif;
  text-align: left;
}
.cid-balance-card__body {
  overflow: visible;
  padding: 18px 20px 20px;
}
.cid-balance-values {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.cid-balance-values--single {
  grid-template-columns: minmax(0, 1fr);
  max-width: 260px;
}
.cid-balance-values--single .cid-balance-value {
  justify-content: center;
}
.cid-balance-value {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 13px 12px;
  border: 1px solid;
  border-radius: 15px;
}
.cid-balance-value--stars {
  border-color: #f1dcaa;
  background: #fffaf0;
}
.cid-balance-value--tokens {
  border-color: #cfe0f8;
  background: #f5f9ff;
}
.cid-balance-value__icon,
.cid-balance-login__icon {
  display: grid;
  flex: 0 0 auto;
  width: 33px;
  height: 33px;
  place-items: center;
  border-radius: 11px;
  color: #fff;
  font-size: 18px;
}
.cid-balance-value--stars .cid-balance-value__icon {
  background: linear-gradient(145deg, #f3b21b, #d58700);
}
.cid-balance-value--tokens .cid-balance-value__icon {
  background: linear-gradient(145deg, #3e93ed, #1454b7);
}
.cid-balance-value div {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.cid-balance-value span:not(.cid-balance-value__icon) {
  color: #65758c;
  font: 800 10px/1.2 'Noto Sans', sans-serif;
}
.cid-balance-value strong {
  color: #172e54;
  font: 900 20px/1 'Noto Sans', sans-serif;
}
.cid-balance-purchases {
  display: grid;
  gap: 9px;
  margin-top: 16px;
}
.cid-balance-purchase {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 12px 13px;
  border: 1px solid #e2e9f4;
  border-radius: 14px;
  color: #142b52;
  background: #fff;
  text-align: left;
  cursor: pointer;
  transition: transform .15s ease, border-color .15s ease, background .15s ease;
}
.cid-balance-purchase:hover,
.cid-balance-purchase:focus-visible {
  border-color: #0962d6;
  background: #f5f9ff;
  outline: none;
  transform: translateY(-1px);
}
.cid-balance-purchase__icon {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 10px;
  color: #fff;
  background: #0962d6;
  font-size: 16px;
}
.cid-balance-purchase:first-child .cid-balance-purchase__icon {
  background: #d98a00;
}
.cid-balance-purchase > span:nth-child(2) {
  display: grid;
  flex: 1;
  gap: 2px;
}
.cid-balance-purchase strong {
  font: 800 12px/1.2 'Noto Sans', sans-serif;
}
.cid-balance-purchase small {
  color: #76859a;
  font: 600 10px/1.25 'Noto Sans', sans-serif;
}
.cid-balance-purchase__arrow {
  color: #0962d6;
  font: 400 24px/1 'Noto Sans', sans-serif;
}
.cid-balance-purchase-detail {
  margin-top: 15px;
  padding-top: 15px;
  border-top: 1px solid #e8edf4;
}
.cid-balance-price {
  margin: 0;
  color: #0962d6;
  font: 900 14px/1.3 'Noto Sans', sans-serif;
}
.cid-balance-country,
.cid-balance-instructions,
.cid-balance-unavailable {
  margin: 0;
  color: #6b7a90;
  font: 600 11px/1.45 'Noto Sans', sans-serif;
}
.cid-balance-summary {
  display: grid;
  gap: 12px;
  margin-top: 14px;
  padding: 13px;
  border: 1px solid #dce8f8;
  background: linear-gradient(145deg, #f7fbff, #fff);
}
.cid-balance-summary__unit {
  display: grid;
  gap: 4px;
}
.cid-balance-summary__unit .cid-balance-country {
  color: #68809f;
  font-size: 10px;
}
.cid-balance-quantity {
  display: grid;
  grid-template-columns: 1fr minmax(90px, 118px);
  align-items: center;
  gap: 10px;
  color: #29466e;
  font: 800 11px/1.25 'Noto Sans', sans-serif;
}
.cid-balance-quantity input {
  width: 100%;
  min-height: 39px;
  border: 1px solid #cbdcf2;
  border-radius: 10px;
  padding: 8px 10px;
  color: #172e54;
  background: #fff;
  font: 900 14px/1 'Noto Sans', sans-serif;
  text-align: left;
}
.cid-balance-quantity input:focus-visible {
  outline: 3px solid rgba(9, 98, 214, .18);
  outline-offset: 1px;
  border-color: #0962d6;
}
.cid-balance-summary__total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding-top: 10px;
  border-top: 1px solid #e5edf8;
  color: #61748e;
  font: 800 10px/1.3 'Noto Sans', sans-serif;
}
.cid-balance-summary__total strong {
  color: #0962d6;
  font: 900 19px/1 'Noto Sans', sans-serif;
  text-align: right;
}
.cid-balance-instructions {
  margin-top: 12px;
  white-space: pre-line;
}
.cid-balance-payment-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}
.cid-balance-payment-button,
.cid-balance-login-button {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  min-height: 39px;
  border: 0;
  border-radius: 10px;
  padding: 9px 10px;
  font: 800 11px/1.2 'Noto Sans', sans-serif;
  white-space: normal;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.cid-balance-payment-button--online,
.cid-balance-login-button {
  color: #fff;
  background: #1266cf;
}
.cid-balance-payment-button--manual {
  color: #1266cf;
  background: #eaf3ff;
}
.cid-balance-networks {
  display: grid;
  gap: 8px;
  margin-top: 13px;
  padding-top: 12px;
  border-top: 1px solid #e8edf4;
}
.cid-balance-networks__label {
  color: #405676;
  font: 800 10px/1.3 'Noto Sans', sans-serif;
}
.cid-balance-network-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
}
.cid-balance-network {
  display: grid;
  justify-items: center;
  gap: 4px;
  min-width: 0;
  padding: 7px 3px;
  border: 1px solid #e1e8f2;
  border-radius: 10px;
  color: #536783;
  background: #fff;
  font: 800 9px/1.1 'Noto Sans', sans-serif;
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease, transform .15s ease;
}
.cid-balance-network:hover,
.cid-balance-network:focus-visible {
  border-color: #7baae8;
  background: #f5f9ff;
  outline: none;
  transform: translateY(-1px);
}
.cid-balance-network.is-selected {
  border-color: #0962d6;
  color: #0962d6;
  background: #edf5ff;
  box-shadow: inset 0 0 0 1px rgba(9, 98, 214, .1);
}
.cid-balance-network__icon {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  border-radius: 7px;
  color: #fff;
  background: #0962d6;
  font: 900 11px/1 'Noto Sans', sans-serif;
}
.cid-balance-network:nth-child(1) .cid-balance-network__icon { background: #f4b400; }
.cid-balance-network:nth-child(2) .cid-balance-network__icon { background: #6937d8; }
.cid-balance-network:nth-child(3) .cid-balance-network__icon { background: #1bbf83; }
.cid-balance-network:nth-child(4) .cid-balance-network__icon { background: #f36c21; }
.cid-balance-network:nth-child(5) .cid-balance-network__icon { background: #079447; }
.cid-balance-payment-button:disabled {
  cursor: wait;
  opacity: .6;
}
.cid-balance-prepare-button {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  min-height: 42px;
  margin-top: 14px;
  border: 0;
  border-radius: 11px;
  padding: 10px 12px;
  color: #fff;
  background: linear-gradient(135deg, #0962d6, #0a3d98);
  box-shadow: 0 8px 18px rgba(9, 98, 214, .16);
  font: 900 11px/1.2 'Noto Sans', sans-serif;
  white-space: normal;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.cid-balance-prepare-button:hover:not(:disabled) {
  filter: brightness(.96);
}
.cid-balance-prepare-button:disabled {
  cursor: not-allowed;
  opacity: .45;
  box-shadow: none;
}
.cid-balance-recap {
  display: grid;
  gap: 9px;
  margin-top: 12px;
  padding: 12px;
  border: 1px solid #c8e7d5;
  border-radius: 14px;
  background: #f5fcf8;
  scroll-margin: 24px;
}
.cid-balance-recap:focus {
  outline: 3px solid rgba(22, 130, 88, .2);
  outline-offset: 2px;
}
.cid-balance-recap[hidden] {
  display: none;
}
.cid-balance-recap__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #146a45;
  font: 900 11px/1.2 'Noto Sans', sans-serif;
}
.cid-balance-recap__head span {
  padding: 4px 7px;
  border-radius: 99px;
  color: #fff;
  background: #168258;
  font-size: 9px;
}
.cid-balance-recap p {
  margin: 0;
  color: #3f6653;
  font: 600 10px/1.45 'Noto Sans', sans-serif;
  white-space: pre-line;
