.anticipation-loading,
.anticipation-muted,
.anticipation-empty {
  margin: 0;
  color: #687b95;
  font: 700 12px/1.45 'Noto Sans', sans-serif;
}
.anticipation-empty {
  width: 96%;
  margin: 12px auto;
