/*  ==== src/shared/unlock-feedback.css ====  */
.cid-unlock-success {
  position: fixed;
  right: 18px;
  bottom: 88px;
  z-index: 1100;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: min(390px, calc(100vw - 32px));
  padding: 15px 16px;
  border: 1px solid #b8e4ca;
  border-radius: 16px;
  background: #f4fff8;
  color: #155b39;
  box-shadow: 0 16px 40px rgba(17, 92, 55, .18);
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .2s ease, transform .2s ease;
  box-sizing: border-box;
}
.cid-unlock-success.is-visible {
  opacity: 1;
  transform: translateY(0);
}
.cid-unlock-success__icon {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #1d9a5d;
  color: #fff;
  font: 900 17px/1 Arial, sans-serif;
}
.cid-unlock-success__copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.cid-unlock-success__copy strong {
  font: 800 14px/1.3 Arial, sans-serif;
}
.cid-unlock-success__copy span,
.cid-unlock-success__copy small {
  font: 600 12px/1.4 Arial, sans-serif;
}
.cid-unlock-success__copy small {
  color: #42745a;
}
.cid-unlock-success__next {
  display: grid;
  gap: 7px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(29, 154, 93, .2);
}
.cid-unlock-success__next span {
  color: #286646;
  font: 700 11px/1.35 Arial, sans-serif;
}
.cid-unlock-success__next button {
  width: fit-content;
  max-width: 100%;
  min-height: 34px;
  padding: 7px 10px;
  border: 1px solid #18864f;
  border-radius: 9px;
  background: #1d9a5d;
  color: #fff;
  cursor: pointer;
  font: 800 11px/1.2 Arial, sans-serif;
}
.cid-unlock-success__next button:hover,
.cid-unlock-success__next button:focus-visible {
  border-color: #12683e;
  background: #167b4b;
  outline: 2px solid rgba(29, 154, 93, .24);
  outline-offset: 2px;
}
.cid-unlock-success__close {
  margin: -4px -5px 0 auto;
  border: 0;
  background: transparent;
  color: #42745a;
  cursor: pointer;
  font: 700 20px/1 Arial, sans-serif;
}
@media (max-width: 560px) {
  .cid-unlock-success {
    right: 12px;
    bottom: 82px;
    width: calc(100vw - 24px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .cid-unlock-success {
    transition: none;
  }
}

