.matrix-calc-results-dialog h2 {
  margin: 0;
  color: #162033;
  font-size: clamp(21px, 5vw, 28px);
  line-height: 1.12;
  overflow-wrap: anywhere;
  text-align: left;
}
.matrix-calc-results-close {
  display: grid;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  place-items: center;
  margin: -3px -3px 0 0;
  padding: 0;
  border: 1px solid #dbe3ef;
  border-radius: 50%;
  background: #fff;
  color: #667085;
  cursor: pointer;
  font-size: 27px;
  font-weight: 400;
  line-height: 1;
  transition: color 160ms ease, background-color 160ms ease,
    border-color 160ms ease, transform 160ms ease;
}
.matrix-calc-results-close:hover,
.matrix-calc-results-close:focus-visible {
  border-color: rgba(23, 105, 224, .35);
  background: #f5f9ff;
  color: #1769e0;
  outline: none;
}
.matrix-calc-results-close:active {
  transform: scale(.96);
}
.matrix-calc-results-description {
  margin: 15px 0 20px;
  color: #667085;
  font-size: 14px;
  line-height: 1.45;
}
.matrix-calc-results-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}
.matrix-calc-results-number {
  display: flex;
  min-width: 0;
  aspect-ratio: 1;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-sizing: border-box;
  border: 1px solid rgba(23, 105, 224, .22);
  border-radius: 15px;
  background: #fff;
  color: #1769e0;
  box-shadow: 0 5px 14px rgba(23, 105, 224, .08);
}
.matrix-calc-results-number strong {
  font-size: clamp(18px, 5vw, 24px);
  font-weight: 900;
  letter-spacing: .015em;
}
.matrix-calc-results-index {
  align-self: flex-start;
  margin-top: 8px;
  color: #98a2b3;
  font-size: 10px;
  font-weight: 800;
}
.matrix-calc-results-done {
  display: block;
  width: 100%;
  min-height: 46px;
  margin-top: 22px;
  padding: 11px 16px;
  border: 0;
  border-radius: 13px;
  background: #1769e0;
  color: #fff;
  cursor: pointer;
  font-size: 16px;
  font-weight: 850;
  line-height: 1.2;
  box-shadow: 0 8px 18px rgba(23, 105, 224, .2);
}
.matrix-calc-results-done:hover,
.matrix-calc-results-done:focus-visible {
  background: #0d4db7;
  outline: none;
}
body.matrix-calc-modal-open {
  overflow: hidden !important;
}
@media (max-width: 380px) {
  .matrix-calc-results-modal {
    padding-left: 11px;
    padding-right: 11px;
  }

  .matrix-calc-results-dialog {
    padding: 18px;
    border-radius: 20px;
  }

  .matrix-calc-results-grid {
    gap: 7px;
  }

  .matrix-calc-results-index {
    display: none;
  }
}

