/*  ==== src/services/public-offers.css ====  */
.cid-public-offers {
  position: relative;
  z-index: 4;
  width: 100%;
  max-width: 1120px;
  box-sizing: border-box;
  margin: 0 auto;
  padding: 12px;
  border: 1px solid color-mix(in srgb, #d47b32 28%, transparent);
  border-radius: 18px;
  background: linear-gradient(135deg, #fff8ef, #ffffff);
  box-shadow: 0 8px 24px rgb(54 37 22 / 8%);
}
.cid-public-offers__heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin: 0 2px 9px;
  color: #202a38;
}
.cid-public-offers__eyebrow {
  color: #b55c1c;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .11em;
  text-transform: uppercase;
}
.cid-public-offers__heading strong {
  font-size: .98rem;
}
.cid-public-offers__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 8px;
  min-width: 0;
}
.cid-public-offer {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
  padding: 11px;
  border: 1px solid rgb(32 42 56 / 10%);
  border-radius: 13px;
  background: rgb(255 255 255 / 82%);
}
.cid-public-offer__topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.cid-public-offer__topline strong {
  overflow: hidden;
  color: #202a38;
  font-size: .9rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cid-public-offer__badge {
  flex: 0 0 auto;
  padding: 3px 6px;
  border-radius: 999px;
  background: #d96f23;
  color: #fff;
  font-size: .63rem;
  font-weight: 800;
  text-transform: uppercase;
}
.cid-public-offer__features {
  min-height: 2.4em;
  margin: 6px 0;
  color: #5d6875;
  font-size: .75rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.cid-public-offer__price {
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
}
.cid-public-offer__price s {
  color: #8b929a;
  font-size: .75rem;
}
.cid-public-offer__price strong {
  color: #b34d12;
  font-size: 1rem;
}
.cid-public-offer small {
  color: #687381;
  font-size: .7rem;
}
.cid-public-offers__empty {
  margin: 0;
  padding: 16px;
  border: 1px solid rgb(32 42 56 / 10%);
  border-radius: 13px;
  color: #687381;
  background: #fff;
  text-align: center;
}
.categories-offers-panel > .cid-public-offers {
  width: 100%;
  margin: 0;
}
.tableaux-collective-offers {
  width: 100%;
  min-width: 0;
}
.tableaux-collective-offers > .cid-public-offers {
  width: 100%;
  max-width: none;
  margin: 0;
}
.cid-public-offers-modal {
  border-color: var(--cid-offer-accent);
  background:
    linear-gradient(135deg,
      var(--cid-offer-tint-strong),
      var(--cid-offer-tint)),
    rgba(255, 255, 255, .74);
  box-shadow:
    0 16px 34px color-mix(in srgb, var(--cid-offer-accent) 18%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .68);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
.cid-public-offers-modal .cid-public-offers__heading {
  color: var(--cid-offer-ink);
}
.cid-public-offers-modal .cid-public-offers__eyebrow {
  color: var(--cid-offer-strong);
}
.cid-public-offer {
  border-color: color-mix(in srgb, var(--cid-offer-accent) 28%, transparent);
  background: rgba(255, 255, 255, .78);
}
.cid-public-offer.is-active {
  border-color: var(--cid-offer-accent);
  background: var(--cid-offer-tint);
  box-shadow: 0 9px 20px color-mix(
    in srgb,
    var(--cid-offer-accent) 20%,
    transparent
  );
  order: -1;
}
.cid-public-offer__toggle {
  display: grid;
  flex: 1 1 auto;
  min-width: 0;
  gap: 3px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--cid-offer-ink);
  cursor: pointer;
  text-align: left;
}
.cid-public-offer__toggle:focus-visible,
.cid-public-offer__purchase:focus-visible {
  outline: 2px solid var(--cid-offer-accent);
  outline-offset: 2px;
}
.cid-public-offer__toggle strong {
  color: var(--cid-offer-ink);
}
.cid-public-offer__toggle small {
  color: var(--cid-offer-strong);
  font-size: .66rem;
  font-weight: 800;
}
.cid-public-offer__active {
  margin: 9px 0 0;
  padding: 8px 9px;
  border-radius: 9px;
  background: var(--cid-offer-tint-strong);
  color: var(--cid-offer-ink);
  font-size: .72rem;
  line-height: 1.4;
}
.cid-public-offer__details {
  display: grid;
  gap: 5px;
  margin: 9px 0;
  padding: 9px 10px;
  border-top: 1px solid color-mix(in srgb, var(--cid-offer-accent) 28%, transparent);
  color: var(--cid-offer-ink);
  font-size: .74rem;
}
.cid-public-offer__details ul {
  display: grid;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.cid-public-offer__details li::before {
  margin-right: 5px;
  color: var(--cid-offer-strong);
  content: '•';
}
.cid-public-offer__purchase {
  width: 100%;
  min-height: 37px;
  margin-top: 10px;
  padding: 8px 11px;
  border: 1px solid var(--cid-offer-accent);
  border-radius: 10px;
  background: var(--cid-offer-accent);
  color: var(--cid-offer-contrast);
  cursor: pointer;
  font-size: .76rem;
  font-weight: 800;
  transition: transform .18s ease, background .18s ease, border-color .18s ease;
}
.cid-public-offer__purchase:hover:not(:disabled) {
  border-color: var(--cid-offer-strong);
  background: var(--cid-offer-strong);
  transform: translateY(-1px);
}
.cid-public-offer__purchase:disabled {
  cursor: wait;
  opacity: .62;
}
.cid-public-offer__purchase.is-access-active:disabled {
  cursor: default;
  border-color: #2a9a64;
  background: #e5f7ed;
  color: #17643f;
  opacity: 1;
}
@media (max-width: 560px) {
  .cid-public-offers {
    padding: 10px;
  }

  .cid-public-offers__heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }
}

