.cid-history-days {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 0 12px 12px;
  border-top: 1px solid #eef1f5;
  background: #fbfcfe;
}
.cid-history-day {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 9px 8px;
  border: 1px solid transparent;
  border-radius: 11px;
  background: #fff;
  color: #1e2d48;
  text-align: left;
  cursor: pointer;
}
.cid-history-day:hover,
.cid-history-day:focus-visible {
  border-color: #bcd7f4;
  background: #f5faff;
  outline: none;
}
.cid-history-day-number {
  display: grid;
  place-items: center;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #eef4fb;
  color: #2766a1;
  font-size: .88rem;
  font-weight: 900;
}
.cid-history-day-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.cid-history-day-copy strong {
  overflow: hidden;
  color: #263750;
  font-size: .78rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cid-history-day-arrow {
  margin-left: auto;
  color: #4388ca;
  font-size: 1rem;
}
.cid-history-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 150px;
  border: 1px solid #e1e7f0;
  border-radius: 15px;
  background: #fff;
  color: #738197;
  font-size: .82rem;
  font-weight: 750;
}
.cid-history-loading-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #ec7921;
  box-shadow: 0 0 0 5px rgba(236,121,33,.12);
  animation: cid-history-pulse .9s ease-in-out infinite alternate;
}
@keyframes cid-history-pulse { to { opacity: .35; transform: scale(.72); } }
.cid-history-selection {
  display: grid;
  gap: 14px;
  margin-top: 18px;
  padding: 16px;
  border: 1px solid #cfe0f2;
  border-radius: 16px;
  background: #f4f9ff;
}
.cid-history-selection-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.cid-history-selection-heading h2 {
  margin: 3px 0 0;
  color: #163866;
  font-size: 1.1rem;
}
.cid-history-section-kicker {
  color: #3478b7;
  font-size: .66rem;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.cid-history-selection-close {
  border: 0;
  background: transparent;
  color: #6a7c95;
  font-size: 1.5rem;
  cursor: pointer;
}
.cid-history-result-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}
.cid-history-result-card {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 12px;
  border: 1px solid #dce8f5;
  border-radius: 12px;
  background: #fff;
}
.resultat-aide-draw-card-heading,
.cid-history-result-line {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.resultat-aide-draw-card-heading {
  color: #1f4978;
  font-size: .82rem;
}
.resultat-aide-draw-card-heading span {
  color: #7d8da4;
}
.cid-history-result-line {
  padding-top: 7px;
  border-top: 1px solid #edf1f6;
  font-size: .72rem;
}
.cid-history-result-line span {
  color: #7b899d;
}
.cid-history-result-line b {
  color: #1d2d48;
  text-align: right;
}
.cid-history-native-link {
  justify-self: start;
  border: 0;
  border-radius: 9px;
  padding: 9px 12px;
  background: #e5f0fd;
  color: #1261bb;
  font-size: .75rem;
  font-weight: 850;
  cursor: pointer;
}
@media (max-width: 720px) {
  .cid-history-filters { grid-template-columns: 1fr 1fr; }
  .cid-history-search { grid-column: 1 / -1; }
  .cid-history-domains { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cid-history-days { grid-template-columns: 1fr; }
  .cid-history-panel { padding-inline: 12px; }
}

/*  ==== src/shared/publication-history.css ====  */
.cid-publication-history {
  width: 100%;
  min-height: 100%;
  padding: 18px 0 150px;
  box-sizing: border-box;
  background: #f97316;
  color: #172033;
}
body.archive-active {
  background: #f97316 !important;
}
body[data-cid-dedicated-view="history"] #historyViewContainer {
  padding: 0 0 calc(148px + env(safe-area-inset-bottom, 0px)) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  background: #f97316 !important;
}
body[data-cid-dedicated-view="history"] .site-header {
  position: fixed !important;
  top: 0 !important;
  right: 0 !important;
  left: 0 !important;
  z-index: 2200 !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}
body[data-cid-dedicated-view="history"] #historyViewMount {
  width: 100%;
  min-height: 100%;
  background: #f97316;
}
.cid-publication-history__header {
  width: min(100% - 32px, 800px);
  margin: 0 auto 12px;
  padding: 12px 16px 10px;
  box-sizing: border-box;
  border-radius: 0;
  background: linear-gradient(135deg, #c2410c, #9a3412);
}
.cid-publication-history__eyebrow {
  color: rgba(255, 255, 255, .86);
  font: 900 10px/1.2 'Noto Sans', sans-serif;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.cid-publication-history__header h1 {
  margin: 4px 0 0;
  color: #fff;
  font: 900 clamp(22px, 5vw, 30px)/1.1 'Noto Sans', sans-serif;
}
.cid-publication-history__header p {
  margin: 6px 0 0;
  color: rgba(255, 255, 255, .88);
  font: 600 12px/1.45 'Noto Sans', sans-serif;
}
.cid-publication-history__sync {
  display: block;
  min-height: 1.15em;
  margin-top: 5px;
  color: rgba(255, 255, 255, .76);
  font: 600 11px/1.35 'Noto Sans', sans-serif;
}
.cid-publication-history__sync[data-state="error"] {
  color: #ffd1d1;
}
.cid-publication-history__sync[data-state="ready"] {
  color: #c5f3db;
}
.cid-publication-history__track {
  display: flex;
  gap: 12px;
  width: 100%;
  padding: 14px 16px 18px;
  overflow-x: auto;
  overflow-y: hidden;
  box-sizing: border-box;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 16px;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x pan-y;
  background: #f97316;
  scrollbar-color: #9a3412 #fed7aa;
}
.cid-publication-history__card {
  display: flex;
  flex: 0 0 min(800px, calc(100% - 24px));
  width: min(800px, calc(100% - 24px));
  max-width: none;
  flex-direction: column;
  scroll-snap-align: start;
  overflow: hidden;
  border: 1px solid #fdba74;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 5px 16px rgba(154, 52, 18, .14);
}
.cid-publication-history__date {
  padding: 12px 14px 8px;
  border-bottom: 1px solid #f1e3d8;
  color: #172033;
}
.cid-publication-history__date strong {
  display: block;
  font: 900 14px/1.2 'Noto Sans', sans-serif;
  text-transform: capitalize;
}
.cid-publication-history__date span {
  display: block;
  margin-top: 3px;
  color: #718096;
  font: 700 10px/1.2 'Noto Sans', sans-serif;
}
.cid-publication-history__body {
  display: grid;
  flex: 1 1 auto;
  align-content: start;
  gap: 9px;
  padding: 12px 14px;
}
.cid-publication-history__body h2 {
  margin: 0;
  color: #0a1840;
  font: 900 16px/1.2 'Noto Sans', sans-serif;
}
.cid-publication-history__body p {
  margin: 0;
  color: #62708a;
  font: 700 11px/1.4 'Noto Sans', sans-serif;
}
.cid-publication-history__card.is-tableau {
  min-height: 520px;
  border: 1px solid #fdba74;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 5px 16px rgba(154, 52, 18, .14);
}
.cid-publication-history__card.is-tableau .cid-publication-history__body {
  min-height: 0;
  padding: 12px 0 16px;
}
.cid-publication-history__tableau-mount {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  background: #fff;
}
.cid-publication-history__tableau-mount > span {
  display: block;
  min-height: 120px;
  padding: 44px 12px;
  color: #62708a;
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}
.cid-publication-history__tableau-clone {
  width: 100% !important;
  min-width: 0 !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
}
.cid-publication-history__tableau-clone > .container {
  min-width: 0 !important;
  max-width: 100% !important;
}
.cid-publication-history__tableau-clone > .table-container {
  width: 100% !important;
  max-width: 100% !important;
  padding-inline: 0 !important;
  margin-inline: 0 !important;
}
.cid-publication-history__tableau-clone
  > .container:nth-child(-n + 2),
.cid-publication-history__tableau-clone
  .created-program-template
  > .container:nth-child(-n + 2) {
  overflow: visible !important;
}
.cid-publication-history__tableau-clone
  .key-info,
.cid-publication-history__tableau-clone
  .key-info p,
.cid-publication-history__tableau-clone
  .key-info strong {
  max-width: 100% !important;
  overflow: visible !important;
  white-space: normal !important;
  overflow-wrap: anywhere !important;
  word-break: normal !important;
}
.cid-publication-history__tableau-clone .key-info {
  line-height: 1.25 !important;
}
.cid-publication-history__tableau-clone .key-info p {
  text-align: center !important;
}
.cid-publication-history__tableau-clone .key-info strong {
  display: inline-block !important;
}
.cid-publication-history__tableau-clone
  .cid-history-placeholder-row td {
  color: rgba(255, 255, 255, .86) !important;
  opacity: .9;
}
.cid-publication-history__tableau-clone.portfolio-universal,
.cid-publication-history__tableau-clone.portfolio-intuition,
.cid-publication-history__tableau-clone.portfolio-oracle,
.cid-publication-history__tableau-clone.portfolio-manual,
.cid-publication-history__tableau-clone.portfolio-lnb {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  align-items: start !important;
  gap: 12px !important;
  padding: 0 12px !important;
}
.cid-publication-history__tableau-clone.portfolio-universal > .container,
.cid-publication-history__tableau-clone.portfolio-intuition > .container,
.cid-publication-history__tableau-clone.portfolio-oracle > .container,
.cid-publication-history__tableau-clone.portfolio-manual > .container,
.cid-publication-history__tableau-clone.portfolio-lnb > .container {
  width: 100% !important;
  min-width: 0 !important;
  max-width: none !important;
  margin: 0 !important;
  box-sizing: border-box !important;
}
.cid-publication-history__tableau-clone.portfolio-universal > .container:nth-child(1),
.cid-publication-history__tableau-clone.portfolio-intuition > .container:nth-child(1),
.cid-publication-history__tableau-clone.portfolio-oracle > .container:nth-child(1),
.cid-publication-history__tableau-clone.portfolio-manual > .container:nth-child(1),
.cid-publication-history__tableau-clone.portfolio-lnb > .container:nth-child(1) {
  grid-column: 1 !important;
}
.cid-publication-history__tableau-clone.portfolio-universal > .container:nth-child(2),
.cid-publication-history__tableau-clone.portfolio-intuition > .container:nth-child(2),
.cid-publication-history__tableau-clone.portfolio-oracle > .container:nth-child(2),
.cid-publication-history__tableau-clone.portfolio-manual > .container:nth-child(2),
.cid-publication-history__tableau-clone.portfolio-lnb > .container:nth-child(2) {
  grid-column: 2 !important;
}
.cid-publication-history__tableau-clone.portfolio-universal > .table-container,
.cid-publication-history__tableau-clone.portfolio-intuition > .table-container,
.cid-publication-history__tableau-clone.portfolio-oracle > .table-container,
.cid-publication-history__tableau-clone.portfolio-manual > .table-container,
.cid-publication-history__tableau-clone.portfolio-lnb > .table-container {
  grid-column: 1 / -1 !important;
  width: 100% !important;
  max-width: 800px !important;
  margin: 0 auto !important;
  box-sizing: border-box !important;
}
.cid-publication-history__tableau-clone.portfolio-universal > .container:nth-child(2) .cross,
.cid-publication-history__tableau-clone.portfolio-intuition > .container:nth-child(2) .cross,
.cid-publication-history__tableau-clone.portfolio-oracle > .container:nth-child(2) .cross,
.cid-publication-history__tableau-clone.portfolio-manual > .container:nth-child(2) .cross,
.cid-publication-history__tableau-clone.portfolio-lnb > .container:nth-child(2) .cross {
  margin-top: 42px !important;
}
.cid-publication-history__tableau-clone.portfolio-universal .title-text,
.cid-publication-history__tableau-clone.portfolio-universal .key-label,
.cid-publication-history__tableau-clone.portfolio-universal .order-label {
  color: #ffd700 !important;
  -webkit-text-fill-color: #ffd700 !important;
}
@media (max-width: 560px) {
  .cid-publication-history__tableau-clone.portfolio-universal,
  .cid-publication-history__tableau-clone.portfolio-intuition,
  .cid-publication-history__tableau-clone.portfolio-oracle,
  .cid-publication-history__tableau-clone.portfolio-manual,
  .cid-publication-history__tableau-clone.portfolio-lnb {
    gap: 12px !important;
    padding: 0 12px !important;
  }

  .cid-publication-history__tableau-clone.portfolio-universal > .table-container,
  .cid-publication-history__tableau-clone.portfolio-intuition > .table-container,
  .cid-publication-history__tableau-clone.portfolio-oracle > .table-container,
  .cid-publication-history__tableau-clone.portfolio-manual > .table-container,
  .cid-publication-history__tableau-clone.portfolio-lnb > .table-container {
    grid-column: 1 / -1 !important;
  }
}
.cid-publication-history__row {
  display: grid;
  gap: 3px;
  padding: 8px 9px;
  border: 1px solid #e8edf4;
  border-radius: 10px;
  background: #f8fafc;
}
.cid-publication-history__row strong {
  color: #1769e0;
  font: 900 10px/1.2 'Noto Sans', sans-serif;
}
.cid-publication-history__row span {
  color: #24324a;
  font: 800 12px/1.3 'Noto Sans', sans-serif;
  word-break: break-word;
}
.cid-publication-history__matrix-program {
  display: grid;
  gap: 7px;
  padding: 10px;
  border: 1px solid #e8edf4;
  border-radius: 11px;
  background: #f8fafc;
}
.cid-publication-history__matrix-program h3 {
  margin: 0;
  color: #1769e0;
  font: 900 12px/1.25 'Noto Sans', sans-serif;
}
.cid-publication-history__matrix-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}
.cid-publication-history__matrix-field {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid #e8edf4;
  border-radius: 8px;
  background: #fff;
}
.cid-publication-history__matrix-field strong {
  color: #69758a;
  font: 900 9px/1.2 'Noto Sans', sans-serif;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.cid-publication-history__matrix-field span {
  color: #24324a;
  font: 800 11px/1.3 'Noto Sans', sans-serif;
  overflow-wrap: anywhere;
}
.cid-publication-history__matrix-values {
  display: grid;
  gap: 3px;
}
.cid-publication-history__matrix-values > span {
  display: block;
  min-height: 1.3em;
  white-space: normal;
}
.cid-publication-history__empty,
.cid-publication-history__locked {
  width: min(100% - 32px, 720px);
  margin: 18px auto;
  padding: 18px;
  border-radius: 14px;
  background: #fff;
  color: #4b5870;
  font: 700 13px/1.5 'Noto Sans', sans-serif;
  text-align: center;
}
.cid-publication-history__placeholder {
  color: #6d7890;
  font-size: 0.85rem;
  font-style: italic;
}
.cid-publication-history__card[data-history-state="stale"] {
  outline: 1px solid rgba(179, 126, 54, 0.22);
}
.cid-publication-history__card[data-history-state="loading"] {
  position: relative;
}
.cid-publication-history__card[data-history-state="loading"]
  .cid-publication-history__placeholder {
  display: grid;
  align-content: start;
  gap: 10px;
  min-height: 300px;
  padding-top: 18px;
  color: transparent;
}
.cid-publication-history__card[data-history-state="loading"]
  .cid-publication-history__placeholder::before,
.cid-publication-history__card[data-history-state="loading"]
  .cid-publication-history__placeholder::after {
  display: block;
  width: 100%;
  height: 12px;
  content: "";
  border-radius: 8px;
  background:
    linear-gradient(
      105deg,
      #edf2f7 8%,
      #f8fafc 18%,
      #edf2f7 33%
    );
  background-size: 220% 100%;
  animation: cid-history-skeleton-shimmer 1.25s linear infinite;
}
.cid-publication-history__card[data-history-state="loading"]
  .cid-publication-history__placeholder::after {
  width: 72%;
  height: 180px;
  margin-top: 6px;
}
@keyframes cid-history-skeleton-shimmer {
  to { background-position: -220% 0; }
}
.cid-publication-history__locked strong {
  display: block;
  margin-bottom: 6px;
  color: #0a1840;
}
.cid-publication-history__unlock {
  margin-top: 12px;
  padding: 9px 13px;
  border: 0;
  border-radius: 9px;
  background: #1769e0;
  color: #fff;
  font: 900 12px/1.2 'Noto Sans', sans-serif;
  cursor: pointer;
}
.tableaux-history-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: max-content;
  min-height: 34px;
  margin: 8px auto 10px;
  padding: 7px 11px;
  border: 1px solid rgba(23, 105, 224, .2);
  border-radius: 9px;
  background: rgba(255, 255, 255, .88);
  color: #1769e0;
  font: 900 11px/1.2 'Noto Sans', sans-serif;
  cursor: pointer;
}
.tableaux-history-button:hover,
.tableaux-history-button:focus-visible {
  background: #1769e0;
  color: #fff;
  outline: 0;
}
.cid-publication-history__social {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 4px 12px;
  border-top: 1px solid rgba(164, 74, 111, .14);
  background: rgba(255, 255, 255, .82);
}
.cid-publication-history__social button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 38px;
  padding: 7px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #68758a;
  cursor: pointer;
  font: 800 11px/1.2 'Noto Sans', sans-serif;
}
.cid-publication-history__social button:hover,
.cid-publication-history__social button:focus-visible,
.cid-publication-history__social button.is-liked {
  background: #fce2ed;
  color: #b02d68;
  outline: 0;
}
.cid-publication-history__social button b {
  min-width: 1.3em;
  color: #26344b;
  text-align: center;
}
.cid-publication-history__social-status {
  min-width: 0;
  margin-left: auto;
  color: #b02d68;
  font-size: 10px;
  font-weight: 800;
  text-align: right;
}
@media (max-width: 560px) {
  .cid-publication-history {
    padding-top: 14px;
  }

  .cid-publication-history__header {
    width: min(100% - 28px, 800px);
  }

  .cid-publication-history__track {
    gap: 10px;
    padding-inline: 14px;
    scroll-padding-inline: 14px;
  }

  .cid-publication-history__matrix-fields {
    grid-template-columns: 1fr;
  }

  .cid-publication-history__card {
    flex-basis: min(92vw, 620px);
    min-height: 500px;
  }

  .cid-publication-history__card.is-tableau {
    min-height: 500px;
  }
}

/*  ==== src/shared/payment-overlays.css ====  */
:root {
  --cid-payment-top-gap: max(
    16px,
    calc(var(--cid-shell-header-height, 50px) + env(safe-area-inset-top, 0px))
  );
  --cid-payment-bottom-gap: max(
    16px,
    calc(var(--cid-shell-footer-height, 56px) + env(safe-area-inset-bottom, 0px))
  );
}
.modal-overlay.cid-payment-overlay.cid-unlock-confirmation {
  position: fixed !important;
  inset: 0 !important;
  z-index: 100000 !important;
  display: flex !important;
  width: 100vw !important;
  height: 100svh !important;
  max-height: var(--cid-visual-height, 100svh) !important;
  min-height: 0 !important;
  box-sizing: border-box !important;
  padding: var(--cid-payment-top-gap)
    max(12px, env(safe-area-inset-right, 0px))
    var(--cid-payment-bottom-gap)
