  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1 / 1;
  object-fit: contain;
}
#cid-home-feed .cid-fb-image-media::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  content: "";
  border-radius: inherit;
  background:
    linear-gradient(
      105deg,
      #edf2f7 8%,
      #f8fafc 18%,
      #edf2f7 33%
    );
  background-size: 220% 100%;
  animation: cid-skeleton-shimmer 1.25s linear infinite;
}
#cid-home-feed .cid-fb-image-media.cid-fb-image-empty,
#cid-home-feed .cid-fb-daily-publication-media {
  min-height: 188px;
}
#cid-home-feed .cid-fb-cross-media {
  min-height: 0;
  padding-block-start: 0;
  padding-block-end: 4px;
}
#cid-home-feed .cid-fb-cross-slot {
  position: relative;
  flex: 0 0 auto;
  width: min(100%, 380px);
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  border-radius: var(--cid-feed-media-radius);
  isolation: isolate;
}
#cid-home-feed .cid-fb-cross-live-host {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  min-height: 0;
  aspect-ratio: 1 / 1;
  overflow: hidden;
